 */
function applyEffectOperation(world, id, vit, operation, potency, stacks, key) {
    if (!vit) return;
    const amount = Math.max(0, potency * stacks);

    if (operation === 'damage') {
        dealDamage(world, {
            target: id,
            amount,
            type: effectKeyToType(key),
            cause: key || 'effect',
        });
        return;
    }

    if (operation === 'heal') {
        applyHealing(world, { target: id, amount, source: id, cause: key || 'effect' });
